#!/usr/bin/env python3
import json
import xml.etree.ElementTree as ET
import os
import re
import zipfile

# ── 1. Read JSON data ──
with open('/root/project_proposal.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

# Budget normalization: remove commas, keep currency symbol
data['예산'] = data['예산'].replace(',', '')

# Month spans for phases
month_spans = {
    '단계1': ' (3개월)',
    '단계2': ' (3개월)',
    '단계3': ' (1개월)',
}

NS = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}
ET.register_namespace('hp', NS['hp'])

base_dir = '/tmp/hwpx_work/template_contents'

# ── 2. Process every XML file ──
for root_dir, dirs, files in os.walk(base_dir):
    for fname in files:
        if not fname.endswith('.xml'):
            continue
        fpath = os.path.join(root_dir, fname)

        tree = ET.parse(fpath)
        root = tree.getroot()

        # Build parent map first
        parent_map = {child: parent for parent in root.iter() for child in parent}

        modified_paras = set()

        # First pass: replace all {{key}} placeholders
        for elem in root.iter():
            if elem.text and '{{' in elem.text:
                def replacer(match):
                    key = match.group(1)
                    if key in data:
                        return data[key]
                    return match.group(0)
                new_text = re.sub(r'\{\{(.*?)\}\}', replacer, elem.text)
                if new_text != elem.text:
                    elem.text = new_text
                    # Mark parent paragraph as modified
                    p = elem
                    while p is not None:
                        if p.tag == '{' + NS['hp'] + '}p':
                            modified_paras.add(p)
                            break
                        p = parent_map.get(p)

        # Second pass: append month spans to phase lines
        # We look for paragraphs whose text contains "1단계:", "2단계:", "3단계:"
        for para in root.iter('{' + NS['hp'] + '}p'):
            # Gather all text in this paragraph
            full_text = ''
            for t_elem in para.iter('{' + NS['hp'] + '}t'):
                if t_elem.text:
                    full_text += t_elem.text

            # Determine which phase this is
            phase_key = None
            if '1단계:' in full_text:
                phase_key = '단계1'
            elif '2단계:' in full_text:
                phase_key = '단계2'
            elif '3단계:' in full_text:
                phase_key = '단계3'

            if phase_key and phase_key in month_spans:
                # Find the last <hp:t> in this paragraph and append month span
                t_elements = list(para.iter('{' + NS['hp'] + '}t'))
                if t_elements:
                    last_t = t_elements[-1]
                    if last_t.text and not last_t.text.endswith(month_spans[phase_key]):
                        last_t.text = last_t.text + month_spans[phase_key]
                        modified_paras.add(para)

        # Third pass: remove layout-cache child elements from modified paragraphs
        # Common names: linesegarray, hp:linesegarray, lineSegArray
        # In ElementTree, the tag will be fully expanded with namespace
        layout_cache_tags = [
            '{' + NS['hp'] + '}linesegarray',
            '{' + NS['hp'] + '}lineSegArray',
        ]
        for para in modified_paras:
            children_to_remove = []
            for child in para:
                # Also handle case where namespace prefix isn't used in tag
                if child.tag in layout_cache_tags or \
                   child.tag.endswith('linesegarray') or \
                   child.tag.endswith('lineSegArray'):
                    children_to_remove.append(child)
            for child in children_to_remove:
                para.remove(child)

        # Write back XML with proper declaration
        tree.write(fpath, encoding='utf-8', xml_declaration=True)

# ── 3. Repackage ZIP ──
output_path = '/root/project_proposal_ready.hwpx'
# Remove old if exists
if os.path.exists(output_path):
    os.remove(output_path)

with zipfile.ZipFile(output_path, 'w', zipfile.ZIP_DEFLATED) as zf:
    for root_dir, dirs, files in os.walk(base_dir):
        for fname in files:
            if fname == '.DS_Store':
                continue
            fpath = os.path.join(root_dir, fname)
            arcname = os.path.relpath(fpath, base_dir)
            # If mimetype, store uncompressed and first
            if arcname == 'mimetype':
                zf.write(fpath, arcname, compress_type=zipfile.ZIP_STORED)
            else:
                zf.write(fpath, arcname)

print("Done.")

